import random, sys
sys.path[:0]=['/workspace/tmp/tests']
from brute import compare

NAMES=['A','B','C','D','E']
def gen_path(rng, maxlen):
    n=rng.randint(0,maxlen)
    return ','.join(rng.choice(NAMES) for _ in range(n))
def gen_pred(rng, depth, nonmatch):
    if depth>=3 or rng.random()<0.45:
        op=rng.choice(['match','match','match','startswith','endswith','contains'])
        maxl = 4 if op!='match' else 4
        if op!='match':
            key=(op,)
            nonmatch.add(op)
        return '%s(%s)'%(op,gen_path(rng,maxl))
    kind=rng.random()
    if kind<0.2:
        return 'not(%s)'%gen_pred(rng,depth+1,nonmatch)
    op=rng.choice(['and','or'])
    return '(%s %s %s)'%(gen_pred(rng,depth+1,nonmatch),op,gen_pred(rng,depth+1,nonmatch))
def gen_policy(rng):
    parts=[]
    for _ in range(rng.randint(0,4)):
        nm=set()
        parts.append('%s %s;'%(gen_pred(rng,0,nm), rng.choice(['allow','allow','drop'])))
    return ' '.join(parts)

def main():
    seed=int(sys.argv[1]) if len(sys.argv)>1 else 1
    count=int(sys.argv[2]) if len(sys.argv)>2 else 300
    rng=random.Random(seed)
    m=rng.randint(2,3)
    reg=[]
    labels=rng.sample(range(1,4294967294),len(NAMES))
    for i,n in enumerate(NAMES):
        reg.append({'name':n,'label':labels[i]})
    bad=0; skipped=0
    for i in range(count):
        p=gen_policy(rng)
        try:
            ok=compare(p,reg,dw=4,dc=4)
        except Exception as e:
            skipped+=1
            continue
        if not ok:
            bad+=1
            print('FAIL seed',seed,i,repr(p))
            if bad>3: break
    print('fuzz seed',seed,'cases',count,'failures',bad,'skipped',skipped)
main()
PYEOF
